import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        bool ok;
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }
        bool isDestroyed = address(c).code.length == 0;
        assertTrue(!(ok && caller != address(this)) || isDestroyed);
    }
