pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound funding amount to a reasonable range
        amount = bound(amount, 1 ether, 100 ether);
        // Owner is msg.sender in setUp (this contract), deal some ETH to the contract
        vm.deal(address(c), amount);
        uint256 balanceBefore = address(c).balance;
        uint256 callerBalanceBefore = address(this).balance;
        c.sudicideAnyone();
        // After selfdestruct, the contract is destroyed and its balance is 0.
        // The correct contract (P) sends funds to msg.sender, the buggy (M) sends to address(0).
        // The universal property: caller's balance must increase by the contract's prior balance.
        // P satisfies this for all amounts; M fails because funds go to address(0) instead of caller.
        assertTrue(address(this).balance == callerBalanceBefore + balanceBefore);
    }
}
